const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
function signClass(v){return (v||'').includes('−')||String(v).startsWith('-')?'neg':((v||'').includes('+')?'pos':'flat')}
function mini(points,color='#22c55e'){const w=92,h=34,step=w/(points.length-1),min=Math.min(...points),max=Math.max(...points),d=points.map((p,i)=>`${i?'L':'M'}${(i*step).toFixed(1)} ${((max-p)/(max-min||1)*(h-8)+4).toFixed(1)}`).join(' ');return `<svg class="spark" viewBox="0 0 ${w} ${h}"><path d="${d}" fill="none" stroke="${color}" stroke-width="2"/><path d="M0 ${h-1} L${w} ${h-1}" stroke="rgba(255,255,255,.08)"/></svg>`}
function bindTabs(){
 $$('[data-tabs]').forEach(group=>{const target=group.dataset.tabs; $$('.tab',group).forEach(btn=>btn.addEventListener('click',()=>{ $$('.tab',group).forEach(b=>b.classList.remove('active'));btn.classList.add('active'); $$(`[data-tab-panel="${target}"]`).forEach(p=>p.classList.toggle('hide',p.dataset.tabValue!==btn.dataset.tab)); if(target==='timeframe') updateChart(btn.dataset.tab); }));});
}
function updateChart(label='1D'){const el=$('#rangeLabel'); if(el) el.textContent=label; const path=$('#pricePath'); if(path){const variants={"1D":"M20 280 L90 250 L150 270 L220 210 L310 230 L390 160 L480 185 L590 115 L700 135 L820 82","5D":"M20 245 L90 260 L160 225 L240 235 L340 170 L430 150 L520 175 L620 130 L720 118 L820 95","1M":"M20 300 L100 260 L180 278 L260 220 L350 200 L430 150 L540 160 L640 110 L730 132 L820 70","3M":"M20 210 L120 240 L220 180 L310 205 L410 150 L520 170 L610 105 L720 90 L820 120","6M":"M20 290 L100 250 L180 230 L260 245 L360 180 L460 145 L560 155 L680 95 L820 60","YTD":"M20 260 L130 230 L250 250 L340 190 L430 200 L520 145 L620 120 L720 86 L820 98","1Y":"M20 310 L120 270 L210 285 L310 215 L420 230 L520 165 L610 140 L720 95 L820 75","5Y":"M20 330 L140 300 L260 250 L370 270 L480 190 L590 155 L700 110 L820 55","All":"M20 340 L120 315 L220 280 L320 300 L430 230 L540 180 L650 135 L740 100 L820 65"}; path.setAttribute('d',variants[label]||variants['1D']);}}
function bindAccordions(){ $$('.accordion-head').forEach(h=>h.addEventListener('click',()=>{const b=h.nextElementSibling;b.classList.toggle('collapsed');h.querySelector('span:last-child').textContent=b.classList.contains('collapsed')?'+':'−';}));}
function bindFilters(){
 $$('[data-filter-tabs]').forEach(group=>{$$('.tab',group).forEach(btn=>btn.addEventListener('click',()=>{ $$('.tab',group).forEach(b=>b.classList.remove('active'));btn.classList.add('active'); const scope=group.dataset.filterTabs; const val=btn.dataset.filter; $$(`[data-filter-scope="${scope}"] [data-cat]`).forEach(card=>card.classList.toggle('hide',val!=='all'&&!card.dataset.cat.includes(val))); }))});
 const video=$('#videosOnly'); if(video) video.addEventListener('click',()=>{video.classList.toggle('active'); const on=video.classList.contains('active'); $$('[data-video]').forEach(c=>c.classList.toggle('hide',on&&c.dataset.video!=='true'));});
}
function bindMarkets(){ $$('.asset-tabs .tab').forEach(t=>t.addEventListener('click',()=>{ $$('.asset-tabs .tab').forEach(x=>x.classList.remove('active'));t.classList.add('active'); const sec=document.getElementById(t.dataset.target); if(sec) sec.scrollIntoView({behavior:'smooth',block:'start'});})); $$('[data-chart-options] .pill').forEach(p=>p.addEventListener('click',()=>{const g=p.parentElement; $$('.pill',g).forEach(x=>x.classList.remove('active'));p.classList.add('active'); $$('.mini-mode').forEach(m=>m.textContent=p.textContent);}));}
function brokerSort(){const group=$('[data-broker-sort]'); if(!group)return; $$('.tab',group).forEach(btn=>btn.addEventListener('click',()=>{ $$('.tab',group).forEach(b=>b.classList.remove('active'));btn.classList.add('active'); const wrap=$('#brokerList'); const cards=$$('.broker-card-wrap',wrap); if(btn.dataset.sort==='rating') cards.sort((a,b)=>parseFloat(b.dataset.rating)-parseFloat(a.dataset.rating)); else cards.sort((a,b)=>parseFloat(b.dataset.accounts)-parseFloat(a.dataset.accounts)); cards.forEach(c=>wrap.appendChild(c));}));}
document.addEventListener('DOMContentLoaded',()=>{bindTabs();bindAccordions();bindFilters();bindMarkets();brokerSort();updateChart('1D');});
