def table(headers, rows, spark=False):
    s='<table class="table"><thead><tr>'+''.join(f'<th>{h}</th>' for h in headers)+('</tr></thead><tbody>')
    for i,r in enumerate(rows):
        s+='<tr>'
        for j,c in enumerate(r):
            cls='sym' if j==0 or (j==1 and len(headers)>3) else signClass(c) if ('%' in str(c) or str(c).startswith(('+','−'))) else ''
            s+=f'<td class="{cls}">{c}</td>'
        if spark:
            pts=[10+i,15+i*2,12,18+i,14,22+i,20,28+i]
            s+=f'<td>{mini(pts,"#22c55e" if i%3 else "#f7525f")}</td>'
        s+='</tr>'
    return s+'</tbody></table>'
