function mini(points,color='#22c55e'){const w=92,h=34,step=w/(points.length-1),min=Math.min(...points),max=Math.max(...points),d=points.map((p,i)=>`${i?'L':'M'}${(i*step).toFixed(1)} ${((max-p)/(max-min||1)*(h-8)+4).toFixed(1)}`).join(' ');return `<svg class="spark" viewBox="0 0 ${w} ${h}"><path d="${d}" fill="none" stroke="${color}" stroke-width="2"/><path d="M0 ${h-1} L${w} ${h-1}" stroke="rgba(255,255,255,.08)"/></svg>`}
